files.src/api.ts:
const USERS: Record<number, { id: number; name: string }> = {
  1: { id: 1, name: "Ada" },
  2: { id: 2, name: "Grace" },
};

export function fetchUsr(id: number): { id: number; name: string } | undefined {
  return USERS[id];
}

files.src/index.ts:
import { fetchUsr } from "./api.ts";

export function getUserName(id: number): string {
  return fetchUsr(id)?.name ?? "unknown";
}

